import re
import sys

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLI = os.path.join(REPO, "fw_c64", "cli")
TXT = os.path.join(CLI, "cli_commands.txt")
MAX_TOKENS = 8
MAX_ARGS = 4
LINE_MAX = 96

